CR = 'change request APG-CR-DSR [number to be given at approval]'
def rec(extra=''):
    return ('Version 1.1 amendment record: amended by ' + CR + ', approved by [approver] on [date], after its Section 18 §6 cascade impact '
            'assessment. The amendment adds text and rewords the version line(s)' + extra + '; every change is listed in that change request. '
            'The lock record above stays as the record of version 1.0. Version 1.0 and its SHA-256 are kept as history.')
